import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

// ─────────────────────────────────────────────────────────────────────────────
// CERTIFICATIONS DATA
// ─────────────────────────────────────────────────────────────────────────────
// HOW TO ADD OR EDIT A CERTIFICATION:
//   1. Copy any object in the `certifications` array below
//   2. Fill in your actual title, organization, year, and credential URL
//   3. For badge images: add your badge to /public/images/certs/
//      and update the `badge` field (e.g. "/images/certs/aws-badge.png")
//      Set badge to null if you don't have one.
//
// FIELDS:
//   id          — unique string key (can be any short label)
//   title       — certification name
//   org         — issuing organization
//   year        — year earned (string)
//   credential  — URL to verify (null if not available)
//   badge       — path to badge image in /public/ (null if none)
//   tags        — short skill keywords shown as chips
// ─────────────────────────────────────────────────────────────────────────────
const certifications = [
  {
    id: "cert-01",
    title: "Web Development Fundamentals",
    org: "Issuing Organization",
    year: "2024",
    // Replace with your actual credential verification URL
    credential: null,
    // Replace with: "/images/certs/cert1-badge.png" once you have a badge
    badge: null,
    tags: ["PHP", "MySQL", "HTML/CSS", "JavaScript"],
  },
  {
    id: "cert-02",
    title: "Mobile App Development",
    org: "Issuing Organization",
    year: "2024",
    credential: null,
    badge: null,
    tags: ["Flutter", "Firebase", "Dart"],
  },
  {
    id: "cert-03",
    title: "Database Management & Design",
    org: "Issuing Organization",
    year: "2023",
    credential: null,
    badge: null,
    tags: ["SQL", "Normalization", "Query Optimization"],
  },
];

// ── Badge placeholder shown when no badge image is provided ──────────────────
function BadgePlaceholder({ isDark }) {
  return (
    <div className={`w-12 h-12 flex items-center justify-center border flex-shrink-0 transition-colors duration-300
      ${isDark ? "border-wire bg-ink-700" : "border-wire-light bg-paper-200"}`}
      aria-hidden="true"
    >
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none"
           stroke={isDark ? "#3a4149" : "#ced4da"} strokeWidth="1.5">
        <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/>
      </svg>
    </div>
  );
}

function CertCard({ cert, isDark }) {
  return (
    <article className={`group flex flex-col border transition-all duration-300 p-6
      ${isDark
        ? "bg-ink-800 border-wire hover:border-ink-500"
        : "bg-white border-wire-light hover:border-gray-300 hover:shadow-sm"}`}
    >
      {/* Top row: badge + meta */}
      <div className="flex items-start gap-4 mb-5">

        {/* Badge — replace with <img> once you have a real badge */}
        {cert.badge ? (
          <img
            src={cert.badge}
            alt={`${cert.title} badge`}
            width="48"
            height="48"
            className="w-12 h-12 object-contain flex-shrink-0"
            loading="lazy"
          />
        ) : (
          <BadgePlaceholder isDark={isDark} />
        )}

        {/* Title + org */}
        <div className="min-w-0">
          <h3 className={`font-display font-semibold text-base leading-snug mb-1
            ${isDark ? "text-stone-200" : "text-gray-900"}`}>
            {cert.title}
          </h3>
          <p className={`text-sm ${isDark ? "text-stone-500" : "text-gray-500"}`}>
            {cert.org}
          </p>
        </div>
      </div>

      {/* Tags */}
      <div className="flex flex-wrap gap-2 mb-5">
        {cert.tags.map((tag) => (
          <span key={tag} className="tag">{tag}</span>
        ))}
      </div>

      {/* Bottom row: year + credential link */}
      <div className={`mt-auto flex items-center justify-between pt-4 border-t
        ${isDark ? "border-wire" : "border-wire-light"}`}>
        <span className={`font-mono text-xs tracking-wider ${isDark ? "text-stone-600" : "text-gray-400"}`}>
          {cert.year}
        </span>

        {cert.credential ? (
          <a
            href={cert.credential}
            target="_blank"
            rel="noopener noreferrer"
            className="font-mono text-xs text-accent-glow hover:text-accent transition-colors flex items-center gap-1.5 tracking-wider"
            aria-label={`Verify ${cert.title} credential`}
          >
            Verify
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none"
                 stroke="currentColor" strokeWidth="2" aria-hidden="true">
              <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6M15 3h6v6M10 14L21 3"/>
            </svg>
          </a>
        ) : (
          <span className={`font-mono text-xs ${isDark ? "text-stone-700" : "text-gray-300"}`}>
            — credential pending
          </span>
        )}
      </div>
    </article>
  );
}

export default function Certifications() {
  const ref = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <section id="certifications" className={`py-28 border-t transition-colors duration-300
      ${isDark ? "bg-ink-950 border-wire" : "bg-paper-50 border-wire-light"}`}>
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Certifications</p>
          <h2 className="section-title text-3xl sm:text-4xl lg:text-5xl max-w-xl">
            Formal recognition<br />
            <span className={isDark ? "text-stone-500" : "text-gray-400"}>of applied skills.</span>
          </h2>
          {/* To edit certifications: update the `certifications` array at the top of this file */}
        </div>

        <div ref={ref} className="fade-up grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {certifications.map((cert) => (
            <CertCard key={cert.id} cert={cert} isDark={isDark} />
          ))}
        </div>

        {/* Callout note */}
        <p className={`mt-10 font-mono text-xs tracking-wider ${isDark ? "text-stone-700" : "text-gray-400"}`}>
          // Additional certifications added as completed
        </p>
      </div>
    </section>
  );
}
